import{_ as e,a0 as i,w as u,s as f,ao as s,I as n,x as o,a1 as r,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"从监狱到 Python | LCTT x X-CMD","titleTemplate":false,"description":"从监狱到 Python | LCTT (202002) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"从监狱到 Python | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"从监狱到 Python | LCTT (202002) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202002/20200112 What I learned going from prison to Python","title":"从监狱到 Python","tag":"202002","desc":""},"relativePath":"202002/20200112 What I learned going from prison to Python.md","filePath":"[post].md"}'),d={name:"202002/20200112 What I learned going from prison to Python.md"};function a(m,t,y,P,g,T){const l=i("Link");return u(),f("div",null,[t[47]||(t[47]=s('<h1 id="从监狱到-python" tabindex="-1">从监狱到 Python <a class="header-anchor" href="#从监狱到-python" aria-label="Permalink to “从监狱到 Python”">​</a></h1><blockquote><p>入狱后，开源编程是如何提供机会的。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/books_programming_languages.jpg?itok=KJcdnXM2" alt="书架上的编程书籍" title="Programming books on a shelf"></p><p>不到一年前，我还在圣昆廷州立监狱服刑，我是无期徒刑。</p><p>我高三的时候，我抢劫了一个人并向他开了枪。现在，我经过一段时间才意识到并承认自己做错了，这是在经历了陪审团审判并看到我的行为带来的恶果后，我知道需要改变自己，我也确实做到了。尽管我对我的行为表示懊悔，但我毕竟开枪打了一个人，并差点杀了他。做这样的事是有后果的，这是理所当然的。所以在我 18 岁的时候，我被判了终身监禁。</p><p>监狱是一个非常可怕的地方；我是不推荐你去的。但是我必须去，所以我去了。我不告诉你具体的细节，但你可以放心，这是一个没有太多动机去改变的地方，许多人在这里养成的坏习惯比他们过去在别处养成的更多。</p><p>我是幸运儿之一。当我在服刑的时候，发生了一些不同寻常的事情。我开始想象自己出狱后的的未来，虽然在这之前，我还是已经在那里度过了我整个成年生活。</p><p>现在你想想：我是黑人，只受过高中教育。我没有工作经历，如果我离开监狱，在被释放前，我还是一个被定罪的重罪犯。当每个雇主看到我的简历，都不会有“我需要雇用这个人”想法，我认为是正常的。</p><p>我不知道我的选择是什么，但我已经下定决心了。我需要做些活下去的事情，并且这和我入狱前的生活一点也不像。</p><h3 id="python-之路" tabindex="-1">Python 之路 <a class="header-anchor" href="#python-之路" aria-label="Permalink to “Python 之路”">​</a></h3>',10)),n("p",null,[t[1]||(t[1]=o("最终，我被关在了圣昆廷州立监狱，我不知道我为何幸运地被关在那里。圣昆廷提供了几个自助和教育编程项目。这些",-1)),r(l,{href:"https://www.dailycal.org/2019/02/27/san-quentin-rehabilitation-programs-offer-inmates-education-a-voice/"},{default:p(()=>[...t[0]||(t[0]=[o("改造机会",-1)])]),_:1}),t[2]||(t[2]=o("帮助囚犯使他们拥有在获释后避免再次犯罪的技能。",-1))]),n("p",null,[t[5]||(t[5]=o("作为其中一个编程项目的一部分，2017 年我通过圣昆廷媒体项目认识了",-1)),r(l,{href:"https://twitter.com/jessicamckellar?lang=en"},{default:p(()=>[...t[3]||(t[3]=[o("杰西卡·麦凯拉",-1)])]),_:1}),t[6]||(t[6]=o("。杰西卡是编程语言 ",-1)),r(l,{href:"https://www.python.org/"},{default:p(()=>[...t[4]||(t[4]=[o("Python",-1)])]),_:1}),t[7]||(t[7]=o(" 的爱好者，她开始向我推荐 Python 有多棒，以及它是刚起步的人学习的完美语言。这就是故事变得比小说更精彩的地方。",-1))]),n("blockquote",null,[n("p",null,[t[11]||(t[11]=o("感谢 ",-1)),r(l,{href:"https://twitter.com/northbaypython?ref_src=twsrc%5Etfw"},{default:p(()=>[...t[8]||(t[8]=[o("@northbaypython",-1)])]),_:1}),t[12]||(t[12]=o(" 让 ",-1)),r(l,{href:"https://twitter.com/ShaStepter?ref_src=twsrc%5Etfw"},{default:p(()=>[...t[9]||(t[9]=[o("@ShaStepter",-1)])]),_:1}),t[13]||(t[13]=o(" 和我重复 ",-1)),r(l,{href:"https://twitter.com/pycon?ref_src=twsrc%5Etfw"},{default:p(()=>[...t[10]||(t[10]=[o("@pycon",-1)])]),_:1}),t[14]||(t[14]=o(" 的主题演讲，让他们被录制下来。我很荣幸与大家分享：",-1))]),n("p",null,[t[16]||(t[16]=o("从监狱到 Pythone: ",-1)),r(l,{href:"https://t.co/rcumoAgZHm"},{default:p(()=>[...t[15]||(t[15]=[o("https://t.co/rcumoAgZHm",-1)])]),_:1})]),n("p",null,[t[18]||(t[18]=o("大规模裁员:如果我们不雇佣被判重罪的人，谁会呢？ ",-1)),r(l,{href:"https://t.co/fENDUFdxfX"},{default:p(()=>[...t[17]||(t[17]=[o("https://t.co/fENDUFdxfX",-1)])]),_:1})]),n("p",null,[r(l,{href:"https://t.co/Kpjo8d3ul6"},{default:p(()=>[...t[19]||(t[19]=[o("pic.Twitter.com/kpjo8d3ul6",-1)])]),_:1})]),n("p",null,[t[21]||(t[21]=o("—杰西卡·麦凯拉（@jessicamckellar）",-1)),r(l,{href:"https://twitter.com/jessicamckellar/status/1191601209917837312?ref_src=twsrc%5Etfw"},{default:p(()=>[...t[20]||(t[20]=[o("2019 年 11 月 5 日",-1)])]),_:1})])]),n("p",null,[t[23]||(t[23]=o("杰西卡向我介绍了一些 Python 视频教程，这些教程是她为一家名叫 ",-1)),r(l,{href:"http://shop.oreilly.com/product/110000448.do"},{default:p(()=>[...t[22]||(t[22]=[o("O’Reilly Media",-1)])]),_:1}),t[24]||(t[24]=o(" 的公司做的，课程是在线的，如果我能接触到它们，那该有多好呀。不幸的是，在监狱里上网是不可能的。但是，我遇到了一个叫 Tim O’Reilly 的人，他最近刚来到圣昆廷。在他访问之后，Tim 从他的公司 O’Reilly Media 公司向监狱的编程班捐赠了大量内容。最终，我拿到了一款平板电脑，上面有杰西卡的 Python 教程，并学会了如何使用这些 Python 教程进行编码。",-1))]),t[48]||(t[48]=s('<p>真是难以置信。背景和生活与我完全不同的陌生人把这些联系在一起，让我学会了编码。</p><h3 id="对-python-社区的热爱" tabindex="-1">对 Python 社区的热爱 <a class="header-anchor" href="#对-python-社区的热爱" aria-label="Permalink to “对 Python 社区的热爱”">​</a></h3><p>在这之后，我开始经常和杰西卡见面，她开始告诉我关于开源社区的情况。我了解到，从根本上说，开源社区就是关于伙伴关系和协作的社区。之所以如此有效，是因为没有人被排除在外。</p><p>对我来说，一个努力寻找自己定位的人，我所看到的是一种非常基本的爱——通过合作和接受的爱，通过接触的爱，通过包容的爱。我渴望成为其中的一部分。所以我继续学习 Python，不幸的是，我无法获得更多的教程，但是我能够从开源社区收集的大量书面知识中获益。我读一切提到 Python 的东西，从平装本到晦涩难懂的杂志文章，我使用平板电脑来解决我读到的 Python 问题。</p><p>我对 Python 和编程的热情不是我的许多同龄人所共有的。除了监狱编程课上的极少数人之外，我认识的其他人都没有提到过编程；一般囚犯都不知道。我认为这是因为有过监禁经历的人无法接触编程，尤其是如果你是有色人种。</p><h3 id="监狱外的-python-生活" tabindex="-1">监狱外的 Python 生活 <a class="header-anchor" href="#监狱外的-python-生活" aria-label="Permalink to “监狱外的 Python 生活”">​</a></h3><p>然而，在 2018 年 8 月 17 日，我得到了生命中的惊喜。时任州长的杰里·布朗将我 27 年的刑期减刑，在服刑将近 19 年后，我被释放出狱了。</p><p>但现实情况是，这也是为什么我认为编程和开源社区如此有价值。我是一名 37 岁的黑人罪犯，没有工作经历，刚刚在监狱服刑 18 年。我有犯罪史，并且现存偏见导致没有多少职业适合我。但是编程是少数例外之一。</p><p>现在，监禁后重返社会的人们迫切需要包容，但当谈及工作场所的多样性以及对多样性的需求时，你真的听不到这个群体被提及或包容。</p>',9)),n("blockquote",null,[t[28]||(t[28]=n("p",null,"还有什么:",-1)),t[29]||(t[29]=n("p",null,"1、背景调查：询问他们在你的公司是如何使用的。",-1)),t[30]||(t[30]=n("p",null,"2、初级角色：删除虚假的、不必要的先决条件，这些条件将排除有记录的合格人员。",-1)),t[31]||(t[31]=n("p",null,"3、积极拓展：与当地再就业项目合作，创建招聘渠道。",-1)),n("p",null,[r(l,{href:"https://t.co/WnzdEUTuxr"},{default:p(()=>[...t[25]||(t[25]=[o("pic.twitter.com/WnzdEUTuxr",-1)])]),_:1})]),n("p",null,[t[27]||(t[27]=o("—杰西卡·麦凯拉（@jessicamckellar）",-1)),r(l,{href:"https://twitter.com/jessicamckellar/status/1127640222504636416?ref_src=twsrc%5Etfw"},{default:p(()=>[...t[26]||(t[26]=[o("2019 年 5 月 12 日",-1)])]),_:1})])]),t[49]||(t[49]=n("p",null,"因此，我想谦卑地挑战开源社区的所有程序员和成员，让他们围绕包容和多样性展开思考。今天，我自豪地站在你们面前，代表一个大多数人都没有想到的群体——以前被监禁的人。但是我们存在，我们渴望证明我们的价值，最重要的是，我们期待被接受。当我们重返社会时，许多挑战等待着我们，我请求你们允许我们有机会展示我们的价值。欢迎我们，接受我们，最重要的是，包容我们。",-1)),t[50]||(t[50]=n("hr",null,null,-1)),n("p",null,[t[33]||(t[33]=o("via: ",-1)),r(l,{href:"https://opensource.com/article/20/1/prison-to-python"},{default:p(()=>[...t[32]||(t[32]=[o("https://opensource.com/article/20/1/prison-to-python",-1)])]),_:1})]),n("p",null,[t[38]||(t[38]=o("作者：",-1)),r(l,{href:"https://opensource.com/users/shastepter"},{default:p(()=>[...t[34]||(t[34]=[o('Shadeed "Sha" Wallace-Stepter',-1)])]),_:1}),t[39]||(t[39]=o(" 选题：",-1)),r(l,{href:"https://github.com/lujun9972"},{default:p(()=>[...t[35]||(t[35]=[o("lujun9972",-1)])]),_:1}),t[40]||(t[40]=o(" 译者：",-1)),r(l,{href:"https://github.com/heguangzhi"},{default:p(()=>[...t[36]||(t[36]=[o("heguangzhi",-1)])]),_:1}),t[41]||(t[41]=o(" 校对：",-1)),r(l,{href:"https://github.com/wxy"},{default:p(()=>[...t[37]||(t[37]=[o("wxy",-1)])]),_:1})]),n("p",null,[t[44]||(t[44]=o("本文由 ",-1)),r(l,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[42]||(t[42]=[o("LCTT",-1)])]),_:1}),t[45]||(t[45]=o(" 原创编译，",-1)),r(l,{href:"https://linux.cn/"},{default:p(()=>[...t[43]||(t[43]=[o("Linux中国",-1)])]),_:1}),t[46]||(t[46]=o(" 荣誉推出",-1))])])}const k=e(d,[["render",a]]);export{b as __pageData,k as default};
